import sys
from collections import defaultdict, deque

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

n, m = read_ints()
roads = defaultdict(list)
for _ in range(m):
    u, v = read_ints()
    roads[u].append(v)

k = read_ints()[0]
path = read_ints()
s, t = path[0], path[-1]

# Precompute shortest paths from each node to t
dist_to_t = {i: float('inf') for i in range(1, n + 1)}
dist_to_t[t] = 0
queue = deque([t])

while queue:
    node = queue.popleft()
    for neighbor in roads[node]:
        if dist_to_t[neighbor] > dist_to_t[node] + 1:
            dist_to_t[neighbor] = dist_to_t[node] + 1
            queue.append(neighbor)

# Calculate minimum rebuilds
min_rebuilds = 0
for i in range(k - 1):
    if dist_to_t[path[i]] > dist_to_t[path[i + 1]] + 1:
        min_rebuilds += 1

# Calculate maximum rebuilds
max_rebuilds = 0
for i in range(k - 1):
    if dist_to_t[path[i]] != dist_to_t[path[i + 1]]:
        max_rebuilds += 1

print(min_rebuilds, max_rebuilds)
